CREATE OR REPLACE FUNCTION public.zad_resolve_login_username(p_username text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key text;
  v_identifier text;
begin
  v_key := lower(trim(coalesce(p_username, '')));

  if char_length(v_key) < 3
     or char_length(v_key) > 24
     or v_key !~ '^[[:alnum:]_-]+$' then
    return null;
  end if;

  select m.login_identifier
  into v_identifier
  from public.username_login_map m
  where m.username_key = v_key
  limit 1;

  return coalesce(
    v_identifier,
    'u_' ||
    md5('zad-login-missing:v1:' || v_key) ||
    md5('zad-login-missing:v2:' || v_key) ||
    '@users.zad-alrouh.invalid'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.zad_change_username(p_new_username text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_username text;
begin
  v_user_id := auth.uid();
  v_username := trim(coalesce(p_new_username, ''));

  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if char_length(v_username) < 3
     or char_length(v_username) > 24
     or v_username !~ '^[[:alnum:]_-]+$' then
    raise exception 'invalid_username';
  end if;

  if not exists (
    select 1
    from public.username_login_map m
    where m.user_id = v_user_id
  ) then
    raise exception 'username_account_required';
  end if;

  update public.profiles
  set username = v_username,
      display_name = v_username,
      updated_at = now()
  where id = v_user_id;

  if not found then
    raise exception 'profile_not_found';
  end if;

  return v_username;

exception
  when unique_violation then
    raise exception 'username_taken'
      using errcode = '23505';
end;
$function$

CREATE OR REPLACE FUNCTION public.zad_calculate_season_streak(p_user_id uuid, p_season integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_day date := (timezone('Africa/Cairo', now()))::date;
  v_start date := date '2026-07-24' + ((p_season - 1) * 14);
  v_count integer := 0;
begin
  if not exists (
    select 1
    from public.point_events pe
    where pe.user_id = p_user_id
      and pe.season_number = p_season
      and pe.event_type in (
        'daily_wird_choice',
        'daily_wird_hizb_1',
        'daily_wird'
      )
      and pe.event_date = v_day
  ) then
    v_day := v_day - 1;
  end if;

  while v_day >= v_start loop
    exit when not exists (
      select 1
      from public.point_events pe
      where pe.user_id = p_user_id
        and pe.season_number = p_season
        and pe.event_type in (
          'daily_wird_choice',
          'daily_wird_hizb_1',
          'daily_wird'
        )
        and pe.event_date = v_day
    );

    v_count := v_count + 1;
    v_day := v_day - 1;
  end loop;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.zad_sync_username_map()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_login_identifier text;
begin
  if new.username is not distinct from old.username then
    return new;
  end if;

  new.username := trim(new.username);

  if char_length(new.username) < 3
     or char_length(new.username) > 24
     or new.username !~ '^[[:alnum:]_-]+$' then
    raise exception 'invalid_username';
  end if;

  select u.email
  into v_login_identifier
  from auth.users u
  where u.id = new.id
    and u.email like 'u_%@users.zad-alrouh.invalid';

  if v_login_identifier is null then
    raise exception 'username_account_required';
  end if;

  insert into public.username_login_map (
    user_id,
    username_key,
    login_identifier
  )
  values (
    new.id,
    lower(new.username),
    v_login_identifier
  )
  on conflict (user_id) do update
  set username_key = excluded.username_key,
      login_identifier = excluded.login_identifier,
      updated_at = now();

  return new;

exception
  when unique_violation then
    raise exception 'username_taken'
      using errcode = '23505';
end;
$function$

CREATE OR REPLACE FUNCTION public.zad_username_available(p_username text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key text;
begin
  v_key := lower(trim(coalesce(p_username, '')));

  if char_length(v_key) < 3
     or char_length(v_key) > 24
     or v_key !~ '^[[:alnum:]_-]+$' then
    return false;
  end if;

  return not exists (
    select 1
    from public.username_login_map m
    where m.username_key = v_key
  )
  and not exists (
    select 1
    from public.profiles p
    where lower(trim(p.username)) = v_key
  );
end;
$function$

