CREATE OR REPLACE FUNCTION public.zad_admin_login(p_username text, p_password text, p_ip text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, message text, session_token text, admin_display_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_admin public.zad_admins%rowtype;
  v_failures integer;
  v_token text;
begin
  delete from public.zad_admin_sessions where expires_at < now();

  select count(*) into v_failures
  from public.zad_admin_login_attempts
  where success = false
    and created_at > now() - interval '15 minutes'
    and (
      (p_ip is not null and ip = p_ip)
      or lower(coalesce(username,'')) = lower(trim(coalesce(p_username,'')))
    );

  if v_failures >= 8 then
    return query select false, 'تم إيقاف محاولات الدخول مؤقتًا. حاول مرة أخرى بعد 15 دقيقة.'::text, null::text, null::text;
    return;
  end if;

  select a.* into v_admin
  from public.zad_admins a
  where a.is_active = true
    and lower(a.username) = lower(trim(coalesce(p_username,'')))
    and a.password_hash = extensions.crypt(coalesce(p_password,''), a.password_hash)
  limit 1;

  if v_admin.id is null then
    insert into public.zad_admin_login_attempts(ip, username, success)
    values (p_ip, trim(coalesce(p_username,'')), false);
    return query select false, 'اسم المستخدم أو كلمة المرور غير صحيحة.'::text, null::text, null::text;
    return;
  end if;

  insert into public.zad_admin_login_attempts(ip, username, success)
  values (p_ip, v_admin.username, true);

  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.zad_admin_sessions(token_hash, admin_id, expires_at)
  values (encode(extensions.digest(v_token, 'sha256'), 'hex'), v_admin.id, now() + interval '12 hours');

  return query select true, 'تم تسجيل الدخول.'::text, v_token, v_admin.display_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.zad_admin_review_submission(p_token text, p_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_admin uuid;
  v_result public.zad_talk_submissions%rowtype;
begin
  select s.admin_id into v_admin
  from public.zad_admin_sessions s
  join public.zad_admins a on a.id=s.admin_id and a.is_active=true
  where s.token_hash = encode(extensions.digest(coalesce(p_token,''), 'sha256'), 'hex')
    and s.expires_at > now()
  limit 1;

  if v_admin is null then
    raise exception 'unauthorized';
  end if;

  if p_action='approve' then
    update public.zad_talk_submissions
      set status='approved', rejection_reason=null, reviewed_at=now(), reviewed_by=v_admin, published_at=coalesce(published_at,now())
    where id=p_id returning * into v_result;
  elsif p_action='reject' then
    update public.zad_talk_submissions
      set status='rejected', rejection_reason=nullif(trim(coalesce(p_reason,'')),''), reviewed_at=now(), reviewed_by=v_admin, published_at=null
    where id=p_id returning * into v_result;
  elsif p_action='delete' then
    delete from public.zad_talk_submissions where id=p_id returning * into v_result;
  else
    raise exception 'invalid_action';
  end if;

  if v_result.id is null then
    raise exception 'not_found';
  end if;

  return jsonb_build_object('ok',true,'id',v_result.id,'action',p_action);
end;
$function$
